from .branding import COMMON_CSS, LOGO_DATA_URI

WORKSPACE_HTML = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Agent White Target Workspace</title><style>
__AW_COMMON_CSS__
.workspace-grid{display:grid;grid-template-columns:320px minmax(0,1fr);gap:10px}.target-list{display:grid;gap:7px;max-height:calc(100vh - 170px);overflow:auto}.target-card{cursor:pointer}.target-card:hover{border-color:var(--aw-green)}.workspace-tabs{display:flex;gap:6px;flex-wrap:wrap}.workspace-tabs button.active{color:var(--aw-green);border-color:var(--aw-green);box-shadow:0 0 14px rgba(0,245,154,.08)}.title{font-weight:800}.action{border-left:3px solid var(--aw-cyan);margin-bottom:8px}.access{border-left:3px solid var(--aw-green);margin-bottom:8px}.history{border-left:3px solid #598578;margin-bottom:8px}.finding{border-left:3px solid var(--aw-amber);margin-bottom:8px}.overview-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.overview-number{font-size:27px;font-weight:900;color:var(--aw-green)}.crumb{font-size:10px;color:var(--aw-cyan);letter-spacing:.6px}.viewer{background:#010605;border:1px solid rgba(0,245,154,.14);border-radius:7px;padding:9px;max-height:60vh;overflow:auto}.viewer img{max-width:100%;height:auto}.pathbar{display:flex;gap:7px;margin-bottom:8px}.pathbar input{flex:1;background:#010605;color:white;border:1px solid rgba(0,245,154,.18);border-radius:7px;padding:8px}@media(max-width:900px){.workspace-grid{grid-template-columns:1fr}.target-list{max-height:none}.overview-grid{grid-template-columns:1fr}}
</style></head><body><div class="aw-app"><aside class="aw-sidebar"><div class="aw-brand"><img class="aw-logo" src="__AW_LOGO__" alt="Agent White logo"><div><div class="aw-wordmark">AGENT <span>WHITE</span></div><div class="aw-tagline">TARGET WORKSPACE</div></div></div><nav class="aw-nav"><a href="/"><span class="ico">▦</span>Dashboard</a><a class="active" href="/workspace"><span class="ico">◎</span>Targets</a><a href="/workspace"><span class="ico">⌘</span>Network</a><a href="/ai"><span class="ico">◉</span>Intelligence</a><a href="/tools"><span class="ico">⌁</span>Tools</a><a href="/api/export" target="_blank"><span class="ico">▤</span>Reports</a></nav><div class="aw-sidebar-foot"><span class="aw-green">● ENGAGEMENT STORE ONLINE</span><br>Saved access and evidence persist locally</div></aside><main class="aw-main"><div class="aw-topbar"><div><div class="aw-wordmark" style="font-size:16px">TARGET <span>WORKSPACE</span></div><div class="aw-muted">Every test is explicit. Results and access points stay saved while you navigate.</div></div><div class="aw-topstatus"><span class="aw-pill ok">Scope Controlled</span><a class="aw-btn blue" href="/tools">Tool Center</a></div></div><div class="workspace-grid"><section class="aw-panel"><div class="aw-panel-head"><h2>ENROLLED TARGETS</h2></div><div id="targets" class="aw-panel-body target-list"><div class="aw-empty">Loading…</div></div></section><section class="aw-panel"><div class="aw-panel-head"><div><h2 id="workspace-title">WORKSPACE</h2><div id="crumb" class="crumb">Select an enrolled target</div></div><span class="aw-right aw-badge ok">PERSISTENT</span></div><div id="workspace" class="aw-panel-body"><div class="aw-empty">Select a target to open its saved engagement.</div></div></section></div></main></div>
<div id="access-modal" class="aw-modal" onclick="if(event.target===this)closeAccess()"><div class="aw-modal-card"><div class="aw-modal-head"><strong id="access-title">SAVED ACCESS</strong><button class="aw-btn aw-right" onclick="closeAccess()">Close</button></div><div class="aw-panel-body"><div id="pathbar" class="pathbar"><input id="access-path" value="/"><button class="aw-btn primary" onclick="loadResource()">Fetch Path</button></div><div id="access-meta" class="aw-card aw-muted">No response loaded.</div><div id="access-viewer" class="viewer"><div class="aw-empty">Choose a saved access point.</div></div></div></div></div><div id="toast" class="aw-toast"></div>
<script>
let state={devices:[]};let ws=null;let tab='tests';let accessCtx=null;const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));function toast(msg,error=false){const e=document.getElementById('toast');e.textContent=msg;e.className='aw-toast'+(error?' error':'');e.style.display='block';setTimeout(()=>e.style.display='none',3500)}async function api(path,opts={}){const r=await fetch(path,{headers:{'Content-Type':'application/json'},cache:'no-store',...opts});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||('Request failed: '+r.status));return d}async function loadTargets(){try{state=await api('/api/state');const rows=(state.devices||[]).filter(d=>d.enrolled),el=document.getElementById('targets');el.innerHTML=rows.length?rows.map(d=>`<div class="aw-card target-card" onclick="openWorkspace('${esc(d.id)}')"><div class="aw-row"><div><div class="title">${esc(d.name)}</div><div class="aw-muted">${esc(d.kind)} · ${esc(d.address||'')}</div></div><span class="aw-badge ok aw-right">ENROLLED</span></div><div class="aw-actions" style="margin-top:7px"><button class="aw-btn primary">Open Workspace</button></div></div>`).join(''):'<div class="aw-empty">No enrolled targets yet. Enroll one from the dashboard.</div>'}catch(e){toast(e.message,true)}}async function openWorkspace(id){try{ws=await api('/api/workspace?device_id='+encodeURIComponent(id));tab='tests';renderWorkspace()}catch(e){toast(e.message,true)}}function setTab(t){tab=t;renderWorkspace()}function renderWorkspace(){if(!ws)return;const d=ws.device;document.getElementById('workspace-title').textContent=d.name||d.id;document.getElementById('crumb').textContent=(d.name||d.id)+' › engagement › '+tab;const tabs=['overview','tests','access','history','findings'];document.getElementById('workspace').innerHTML=`<div class="workspace-tabs">${tabs.map(t=>`<button class="aw-btn ${tab===t?'active':''}" onclick="setTab('${t}')">${t.toUpperCase()}</button>`).join('')}<button class="aw-btn danger aw-right" onclick="clearWorkspace()">Clear Saved Workspace</button></div><div style="margin-top:9px">${renderTab()}</div>`}function renderTab(){if(tab==='overview')return overview();if(tab==='tests')return tests();if(tab==='access')return access();if(tab==='history')return history();return findings()}function overview(){const e=ws.engagement||{};return`<div class="overview-grid"><div class="aw-card"><div class="aw-muted">SAVED TESTS</div><div class="overview-number">${(ws.action_runs||[]).length}</div></div><div class="aw-card"><div class="aw-muted">SAVED ACCESS</div><div class="overview-number">${(ws.access_sessions||[]).length}</div></div><div class="aw-card"><div class="aw-muted">FINDINGS</div><div class="overview-number">${(ws.findings||[]).length}</div></div></div><div class="aw-card" style="margin-top:8px"><div class="title">Engagement state</div><div class="aw-muted">Status: ${esc(e.status||'saved')}<br>Started: ${esc(e.started_at||'')}<br>Updated: ${esc(e.updated_at||'')}</div></div>`}function tests(){const rows=ws.available_actions||[];if(!rows.length)return'<div class="aw-empty">No actions available while this target is outside active scope.</div>';return rows.map(a=>`<div class="aw-card action"><div class="aw-row"><div><div class="title">${esc(a.label)}</div><div class="aw-muted">${esc(a.description)}</div></div><span class="aw-badge ${a.effect==='PASSIVE'?'ok':''} aw-right">${esc(a.effect)}</span></div><div class="aw-actions" style="margin-top:8px">${a.kind==='access'?`<button class="aw-btn primary" onclick="openSavedAccess(${Number(a.parameters?.port||0)})">Open Saved Access</button>`:`<button class="aw-btn primary" onclick="runAction('${esc(a.id)}')">Run This Test</button>`}</div></div>`).join('')}async function runAction(actionId){toast('Running only the selected test…');try{const r=await api('/api/action',{method:'POST',body:JSON.stringify({device_id:ws.device.id,action_id:actionId})});ws=r.workspace;renderWorkspace();toast(r.result?.summary||'Test complete. Waiting for your next selection.');if(r.inspection)showBleProof(r.inspection)}catch(e){toast(e.message,true);await openWorkspace(ws.device.id)}}function access(){const rows=ws.access_sessions||[];if(!rows.length)return'<div class="aw-empty">No saved access points yet.</div>';return rows.map(s=>`<div class="aw-card access"><div class="aw-row"><div><div class="title">${esc(s.label)}</div><div class="aw-muted">Last seen: ${esc(s.last_seen_at)}</div></div><span class="aw-badge ${s.status==='ready'?'ok':''} aw-right">${esc(s.status)}</span></div><pre class="aw-pre" style="margin-top:7px">${esc(JSON.stringify(s.endpoint||{},null,2))}</pre><div class="aw-actions" style="margin-top:7px">${s.kind==='http'?`<button class="aw-btn primary" onclick="openSavedAccess(${Number((s.endpoint||{}).port||0)},'${esc((s.endpoint||{}).path||'/')}')">Return to Access</button>`:''}${s.kind==='bluetooth'?`<button class="aw-btn primary" onclick="runAction('bluetooth.gatt.inspect')">Reconnect & Inspect</button>`:''}<button class="aw-btn" onclick="setTab('history')">View Test History</button><button class="aw-btn" onclick="setTab('findings')">View Fix Guidance</button></div></div>`).join('')}function history(){const rows=ws.action_runs||[];if(!rows.length)return'<div class="aw-empty">No tests have been run yet.</div>';return rows.map(r=>`<div class="aw-card history"><div class="aw-row"><div><div class="title">${esc(r.label)}</div><div class="aw-muted">${esc(r.started_at)}${r.completed_at?' → '+esc(r.completed_at):''}</div></div><span class="aw-badge ${r.status==='success'?'ok':''} aw-right">${esc(r.status)}</span></div><div class="aw-muted">Elapsed: ${r.elapsed_ms??'—'} ms · ${esc(r.action_id)}</div><pre class="aw-pre" style="margin-top:7px">${esc(JSON.stringify(r.result||{},null,2))}</pre></div>`).join('')}function findings(){const rows=ws.findings||[];if(!rows.length)return'<div class="aw-empty">No findings recorded yet.</div>';return rows.map(f=>`<div class="aw-card finding"><div class="aw-row"><div class="title">${esc(f.title)}</div><span class="aw-badge aw-right">${esc(f.severity)}</span></div><div class="aw-muted">${esc(f.created_at)} · ${esc(f.status)}</div><pre class="aw-pre" style="margin-top:7px">${esc(JSON.stringify(f.proof||{},null,2))}</pre><div style="margin-top:7px"><strong>How to fix:</strong> ${esc(f.remediation)}</div></div>`).join('')}function openSavedAccess(port,path='/'){accessCtx={device_id:ws.device.id,port:Number(port)};document.getElementById('access-title').textContent='SAVED HTTP ACCESS · TCP/'+port;document.getElementById('pathbar').style.display='flex';document.getElementById('access-path').value=path||'/';document.getElementById('access-meta').textContent='Saved access point ready. Choose a path to retrieve.';document.getElementById('access-viewer').innerHTML='<div class="aw-empty">No response loaded in this view yet.</div>';document.getElementById('access-modal').classList.add('open')}async function loadResource(){if(!accessCtx)return;const path=document.getElementById('access-path').value||'/';try{const r=await api('/api/resource',{method:'POST',body:JSON.stringify({...accessCtx,path})});ws=r.workspace;renderWorkspace();const x=r.resource||{};document.getElementById('access-meta').textContent=`HTTP ${x.status||0} ${x.reason||''}\n${x.content_type||''}\n${x.bytes_captured||0} bytes\nSHA-256: ${x.sha256||''}`;const v=document.getElementById('access-viewer');if(x.image_data_url)v.innerHTML=`<img src="${x.image_data_url}" alt="Returned material">`;else if(x.text_preview!==undefined)v.innerHTML=`<pre class="aw-pre">${esc(x.text_preview)}</pre>`;else v.innerHTML=`<pre class="aw-pre">${esc(x.hex_preview||'No response body')}</pre>`;toast(r.verified?'Access verified and saved.':'Service responded but access was challenged or blocked.')}catch(e){toast(e.message,true)}}function showBleProof(x){accessCtx=null;document.getElementById('access-title').textContent='BLE ACCESS PROOF';document.getElementById('pathbar').style.display='none';document.getElementById('access-meta').textContent=`Connected: ${!!x.connected}\nServices: ${x.service_count||0}\nCharacteristics: ${x.characteristic_count||0}\nReadable: ${x.readable_count||0}`;document.getElementById('access-viewer').innerHTML=`<pre class="aw-pre">${esc(JSON.stringify(x.services||[],null,2))}</pre>`;document.getElementById('access-modal').classList.add('open')}function closeAccess(){document.getElementById('access-modal').classList.remove('open');accessCtx=null}async function clearWorkspace(){if(!confirm('Clear saved tests, access points, and findings for this target?'))return;try{const r=await api('/api/workspace/clear',{method:'POST',body:JSON.stringify({device_id:ws.device.id})});ws=r.workspace;renderWorkspace();toast('Saved workspace cleared; enrollment remains.')}catch(e){toast(e.message,true)}}loadTargets();
</script></body></html>'''
WORKSPACE_HTML = WORKSPACE_HTML.replace("__AW_COMMON_CSS__", COMMON_CSS).replace("__AW_LOGO__", LOGO_DATA_URI)
